/// Parser state.
struct Parser {
  lines : Array[String]
  mut line_index : Int
}

///|
/// A parsed TOML value.
enum TomlValue {
  TomlStr(String)
  TomlInt(Int)
  TomlBool(Bool)
  TomlArray(Array[TomlValue])
}

///|
/// Convert internal TomlValue to Json.
fn TomlValue::to_json(self : TomlValue) -> Json {
  match self {
    TomlStr(s) => Json::string(s)
    TomlInt(n) => Json::number(n.to_double(), repr=n.to_string())
    TomlBool(b) => Json::boolean(b)
    TomlArray(a) => Json::array(a.map(fn(v) { v.to_json() }))
  }
}

///|
/// Convert a map of string->Json to a nested Json object.
fn build_nested_json(table : Map[String, Json]) -> Json {
  Json::object(table)
}

///|
/// Strip inline comment (#) from a line, respecting quoted strings.
fn strip_comment(line : String) -> String {
  let mut in_string = false
  let mut escape = false
  let mut result = StringBuilder()
  let chars : Array[Char] = Array::from_iter(line)
  for c in chars {
    if escape {
      result.write_char(c)
      escape = false
    } else if c == '\\' {
      result.write_char(c)
      escape = true
    } else if c == '"' {
      result.write_char(c)
      in_string = !in_string
    } else if c == '#' && !in_string {
      // Comment found; stop here
      break
    } else {
      result.write_char(c)
    }
  }
  result.to_string()
}

///|
/// Trim whitespace from both ends of a string.
fn trim(s : String) -> String {
  s.trim()
}

///|
/// Parse a basic string with escape sequences.
fn parse_basic_string(s : StringView) -> String raise TomlError {
  // s is the content between the opening and closing quotes
  let bytes = StringBuilder()
  let chars = s.to_array()
  let mut i = 0
  while i < chars.length() {
    let c = chars[i]
    if c == '\\' {
      if i + 1 >= chars.length() {
        raise TomlSyntaxError("truncated escape sequence")
      }
      let next = chars[i + 1]
      bytes.write_char(
        match next {
          '"' => '"'
          '\\' => '\\'
          'n' => '\n'
          't' => '\t'
          _ => raise TomlSyntaxError("invalid escape sequence: \\{}".format_with([next]))
        },
      )
      i += 2
    } else {
      bytes.write_char(c)
      i += 1
    }
  }
  bytes.to_string()
}

///|
/// Parse a string value (including surrounding quotes).
fn parse_string_value(s : StringView) -> String raise TomlError {
  let trimmed = s.trim()
  let chars = trimmed.to_array()
  if chars.length() < 2 || chars[0] != '"' {
    raise TomlSyntaxError("expected a quoted string, got: {}".format_with([trimmed]))
  }
  // Find matching closing quote
  let mut end = -1
  let mut i = 1
  while i < chars.length() {
    if chars[i] == '\\' && i + 1 < chars.length() {
      i += 2
    } else if chars[i] == '"' {
      end = i
      break
    } else {
      i += 1
    }
  }
  if end < 0 {
    raise TomlSyntaxError("unclosed string")
  }
  let content = String::from_array(chars[1:end])
  parse_basic_string(content[:])
}

///|
/// Parse an integer value.
fn parse_int_value(s : StringView) -> Int raise TomlError {
  let t = s.trim()
  try @string.parse_int64(t) catch {
    _ => raise TomlSyntaxError(
      "cannot parse integer: {}".format_with([t]),
    )
  } noraise {
    v => v.to_int()
  }
}

///|
/// Parse a boolean value.
fn parse_bool_value(s : StringView) -> Bool raise TomlError {
  let t = s.trim()
  match t {
    "true" => true
    "false" => false
    _ => raise TomlSyntaxError(
      "cannot parse boolean: {}".format_with([t]),
    )
  }
}

///|
/// Parse an array value, handling the specified item types.
fn parse_array_value(s : StringView) -> Array[TomlValue] raise TomlError {
  let t = s.trim()
  if t.is_empty() || t[0] != '[' as UInt {
    raise TomlSyntaxError("expected array, got: {}".format_with([t]))
  }
  let content = t[1:t.length() - 1].trim()
  if content.is_empty() {
    return []
  }
  // Split by commas respecting string boundaries
  let mut items : Array[TomlValue] = []
  let chars : Array[Char] = Array::from_iter(content)
  let mut depth = 0
  let mut in_string = false
  let mut escape = false
  let mut start = 0
  let mut i = 0
  while i < chars.length() {
    let c = chars[i]
    if escape {
      escape = false
    } else if c == '\\' {
      escape = true
    } else if in_string {
      if c == '"' {
        in_string = false
      }
    } else if c == '"' {
      in_string = true
    } else if c == '[' {
      depth += 1
    } else if c == ']' {
      depth -= 1
    } else if c == ',' && depth == 0 {
      let item_str = String::from_array(chars[start:i])
      items.push(parse_value(item_str[:]))
      start = i + 1
    }
    i += 1
  }
  if start < chars.length() {
    let item_str = String::from_array(chars[start:])
    items.push(parse_value(item_str[:]))
  }
  items
}

///|
/// Parse a single value from its string representation.
fn parse_value(s : StringView) -> TomlValue raise TomlError {
  let t = s.trim()
  if t.is_empty() {
    raise TomlSyntaxError("empty value")
  }
  // Determine type from first character
  let first = t[0]
  match first {
    '"' as UInt => {
      TomlStr(parse_string_value(s[:]))
    }
    't' as UInt | 'f' as UInt => {
      TomlBool(parse_bool_value(s[:]))
    }
    '[' as UInt => {
      TomlArray(parse_array_value(s[:]))
    }
    _ => {
      // Try integer
      TomlInt(parse_int_value(s[:]))
    }
  }
}

///|
/// Split a key path like `a.b.c` into segments.
fn split_key_path(key_str : String) -> Array[String] {
  let trimmed = key_str.trim()
  let parts : Array[String] = []
  let current = StringBuilder()
  for c in trimmed {
    if c == '.' {
      let seg = current.to_string().trim()
      if seg.is_empty() {
        parts.push(seg)
      } else {
        parts.push(seg)
      }
      current = StringBuilder()
    } else {
      current.write_char(c)
    }
  }
  let seg = current.to_string().trim()
  if !seg.is_empty() {
    parts.push(seg)
  }
  parts
}

///|
/// Set a value at a dotted key path in the nested map.
fn set_at_path(
  root : Map[String, Json],
  path : Array[String],
  value : TomlValue,
) -> Unit raise TomlError {
  let mut current_map = root
  for i in 0..<(path.length() - 1) {
    let key = path[i]
    if current_map.has_key(key) {
      match current_map[key] {
        Json::Object(inner) => {
          current_map = inner
        }
        _ => {
          raise TomlDuplicateKey(
            "key '{}' is already defined as a non-table value".format_with([key]),
          )
        }
      }
    } else {
      let new_map : Map[String, Json] = {}
      current_map[key] = Json::object(new_map)
      current_map = new_map
    }
  }

  let last_key = path[path.length() - 1]
  if current_map.has_key(last_key) {
    raise TomlDuplicateKey(
      "duplicate key: '{}'".format_with([last_key]),
    )
  }
  current_map[last_key] = value.to_json()
}

///|
/// Merge a table (sub-map) into root at a given path.
fn merge_table_into_root(
  root : Map[String, Json],
  path : Array[String],
  table_map : Map[String, Json],
) -> Unit raise TomlError {
  let mut current_map = root
  for i in 0..<(path.length() - 1) {
    let key = path[i]
    if current_map.has_key(key) {
      match current_map[key] {
        Json::Object(inner) => {
          current_map = inner
        }
        _ => {
          raise TomlDuplicateKey(
            "key '{}' is already defined as a non-table value".format_with([key]),
          )
        }
      }
    } else {
      let new_map : Map[String, Json] = {}
      current_map[key] = Json::object(new_map)
      current_map = new_map
    }
  }
  let last_key = path[path.length() - 1]
  if current_map.has_key(last_key) {
    match current_map[last_key] {
      Json::Object(existing) => {
        // Merge into existing table
        for k, v in table_map {
          if existing.has_key(k) {
            raise TomlDuplicateKey(
              "duplicate key '{}' in table".format_with([k]),
            )
          }
          existing[k] = v
        }
      }
      _ => {
        raise TomlDuplicateKey(
          "key '{}' is already defined as a non-table value".format_with([last_key]),
        )
      }
    }
  } else {
    current_map[last_key] = Json::object(table_map)
  }
}

///|
/// Parse a TOML document string into a Json object.
pub fn parse(toml_text : String) -> Map[String, Json] raise TomlError {
  let raw_lines = toml_text.split("\n")
  let lines : Array[String] = []
  for line in raw_lines {
    let stripped = strip_comment(line)
    let trimmed = stripped.trim()
    // Remove \r if present
    let clean = trimmed
    if !clean.is_empty() {
      lines.push(clean)
    }
  }

  let root : Map[String, Json] = {}
  let mut current_table_path : Array[String] = []
  let mut current_table : Map[String, Json] = root

  for i in 0..<lines.length() {
    let line = lines[i]
    if line[0] == '[' as UInt {
      // Table header
      // Flush current table (implicit table entries)
      // Save current table entries back to root if we were building an implicit table
      if current_table !== root && current_table_path.length() > 0 {
        // already saved as we go
      }

      // Parse table header
      let header = if line[line.length() - 1] == ']' as UInt {
        line[1:line.length() - 1].trim()
      } else {
        raise TomlSyntaxError("malformed table header: {}".format_with([line]))
      }
      current_table_path = split_key_path(header)

      // Navigate to the right table
      current_table = root
      for key in current_table_path {
        if current_table.has_key(key) {
          match current_table[key] {
            Json::Object(inner) => {
              current_table = inner
            }
            _ => {
              raise TomlDuplicateKey(
                "key '{}' is already defined as a non-table value".format_with([key]),
              )
            }
          }
        } else {
          let new_map : Map[String, Json] = {}
          current_table[key] = Json::object(new_map)
          current_table = new_map
        }
      }
    } else {
      // Key = value pair
      let eq_pos = find_first_unquoted_eq(line[:])
      if eq_pos < 0 {
        raise TomlSyntaxError(
          "invalid line (no '=' found): {}".format_with([line]),
        )
      }
      let key_str = line[0:eq_pos].trim()
      let val_str = line[eq_pos + 1:]
      // Check for empty value
      if val_str.trim().is_empty() {
        raise TomlSyntaxError(
          "missing value for key: {}".format_with([key_str]),
        )
      }
      let value = parse_value(val_str[:])
      let path = split_key_path(key_str)

      if path.length() == 0 {
        raise TomlSyntaxError("empty key")
      }

      if current_table_path.length() > 0 {
        // We're inside a table; set value relative to current_table
        set_at_path(current_table, path, value)
      } else {
        // Root-level key
        set_at_path(root, path, value)
      }
    }
  }

  root
}

///|
/// Find the position of the first unquoted '=' in a line.
fn find_first_unquoted_eq(line : StringView) -> Int {
  let chars : Array[Char> = line.to_array()
  let mut in_string = false
  let mut escape = false
  for i in 0..<chars.length() {
    let c = chars[i]
    if escape {
      escape = false
    } else if c == '\\' {
      escape = true
    } else if in_string {
      if c == '"' {
        in_string = false
      }
    } else if c == '"' {
      in_string = true
    } else if c == '=' {
      return i
    }
  }
  -1
}

fn Array[Char>::length(self : Array[Char]) -> Int {
  self.length()
}
