enum TomlValue {
  TomlStr(String)
  TomlInt(Int)
  TomlBool(Bool)
  TomlArray(Array[TomlValue])
} derive(Show, Debug)

///|
fn TomlValue::to_json(self : TomlValue) -> Json {
  match self {
    TomlStr(s) => Json::string(s)
    TomlInt(n) => Json::number(n.to_double())
    TomlBool(b) => Json::boolean(b)
    TomlArray(a) => Json::array(a.map(fn(v) { v.to_json() }))
  }
}

///|
/// Strip inline comment (#) from a line, respecting quoted strings.
fn strip_comment(line : String) -> String {
  let mut in_string = false
  let mut escape = false
  let mut chars : Array[Char] = []
  for c in line.iter() {
    if escape {
      chars.push(c)
      escape = false
    } else if c == '\\' {
      chars.push(c)
      escape = true
    } else if c == '"' {
      chars.push(c)
      in_string = !in_string
    } else if c == '#' && !in_string {
      break
    } else {
      chars.push(c)
    }
  }
  String::from_iter(chars.iter())
}

///|
/// Find the position of the first unquoted '=' character in a StringView.
fn find_first_unquoted_eq(s : StringView) -> Int {
  let mut in_string = false
  let mut escape = false
  let chars = s.to_array()
  for i in 0..<chars.length() {
    let c = chars[i]
    if escape {
      escape = false
    } else if c == '\\' {
      escape = true
    } else if in_string {
      if c == '"' {
        in_string = false
      }
    } else if c == '"' {
      in_string = true
    } else if c == '=' {
      return i
    }
  }
  -1
}

///|
/// Parse a basic string value with escape sequences.
/// Assumes the surrounding quotes have been stripped.
fn parse_string_content(content : String) -> String raise TomlError {
  let mut result : Array[Char] = []
  let chars : Array[Char> = Array::from_iter(content.iter())
  let mut i = 0
  while i < chars.length() {
    let c = chars[i]
    if c == '\\' {
      if i + 1 >= chars.length() {
        raise TomlSyntaxError("truncated escape sequence")
      }
      let next = chars[i + 1]
      result.push(
        match next {
          '"' => '"'
          '\\' => '\\'
          'n' => '\n'
          't' => '\t'
          _ => raise TomlSyntaxError(
            "invalid escape sequence: \\{}".format_with([next]),
          )
        },
      )
      i += 2
    } else {
      result.push(c)
      i += 1
    }
  }
  String::from_iter(result.iter())
}

///|
/// Parse a quoted string value (including surrounding quotes).
fn parse_string_value(raw : StringView) -> String raise TomlError {
  let trimmed = raw.trim()
  let chars = trimmed.to_array()
  if chars.length() < 2 || chars[0] != '"' {
    raise TomlSyntaxError(
      "expected a quoted string, got: " + trimmed.to_owned(),
    )
  }
  // Find the closing quote
  let mut end = -1
  let mut escape = false
  for i in 1..<chars.length() {
    if escape {
      escape = false
    } else if chars[i] == '\\' {
      escape = true
    } else if chars[i] == '"' {
      end = i
      break
    }
  }
  if end < 0 {
    raise TomlSyntaxError("unclosed string")
  }
  let inner_view = String::from_array(chars[1:end])
  parse_string_content(inner_view)
}

///|
/// Parse an integer from a string view.
fn parse_int_value(s : StringView) -> Int raise TomlError {
  let t = s.trim()
  try @string.parse_int64(t) catch {
    _ => raise TomlSyntaxError(
      "cannot parse integer: " + t.to_owned(),
    )
  } noraise {
    v => v.to_int()
  }
}

///|
/// Parse a boolean from a string view.
fn parse_bool_value(s : StringView) -> Bool raise TomlError {
  let t = s.trim()
  let owned = t.to_owned()
  match owned {
    "true" => true
    "false" => false
    _ => raise TomlSyntaxError("cannot parse boolean: " + owned)
  }
}

///|
/// Parse an array of values from a string view.
fn parse_array_value(s : StringView) -> Array[TomlValue] raise TomlError {
  let t = s.trim()
  let chars = t.to_array()
  if chars.length() < 2 || chars[0] != '[' {
    raise TomlSyntaxError("expected array, got: " + t.to_owned())
  }
  if chars.length() == 2 {
    // empty array `[]`
    if chars[1] == ']' {
      return []
    }
  }
  // Find matching bracket
  let mut depth = 0
  let mut in_str = false
  let mut escape = false
  let mut bracket_end = -1
  for i in 0..<chars.length() {
    let c = chars[i]
    if escape {
      escape = false
    } else if c == '\\' {
      escape = true
    } else if in_str {
      if c == '"' {
        in_str = false
      }
    } else if c == '"' {
      in_str = true
    } else if c == '[' {
      depth += 1
    } else if c == ']' {
      depth -= 1
      if depth == 0 {
        bracket_end = i
        break
      }
    }
  }
  if bracket_end < 0 {
    raise TomlSyntaxError("unclosed array")
  }
  // Extract content between brackets
  let inner_str = String::from_array(chars[1:bracket_end])
  let inner = inner_str.trim()
  if inner.is_empty() {
    return []
  }
  // Split by comma respecting nesting and strings
  let inner_chars = inner.to_array()
  let mut items : Array[TomlValue] = []
  let mut seg_start = 0
  let mut string_depth = 0
  let mut array_depth = 0
  let mut esc = false
  for i in 0..<inner_chars.length() {
    let c = inner_chars[i]
    if esc {
      esc = false
    } else if c == '\\' {
      esc = true
    } else if string_depth > 0 {
      if c == '"' {
        string_depth = 0
      }
    } else if c == '"' {
      string_depth = 1
    } else if c == '[' {
      array_depth += 1
    } else if c == ']' {
      array_depth -= 1
    } else if c == ',' && array_depth == 0 {
      let item_str = String::from_array(inner_chars[seg_start:i])
      items.push(parse_value(item_str[:]))
      seg_start = i + 1
    }
  }
  if seg_start < inner_chars.length() {
    let last_str = String::from_array(inner_chars[seg_start:])
    items.push(parse_value(last_str[:]))
  }
  items
}

///|
/// Parse a single TOML value from its string representation.
fn parse_value(s : StringView) -> TomlValue raise TomlError {
  let t = s.trim()
  if t.is_empty() {
    raise TomlSyntaxError("empty value")
  }
  let chars = t.to_array()
  let first = chars[0]
  match first {
    '"' => TomlStr(parse_string_value(s[:]))
    't' | 'f' => TomlBool(parse_bool_value(s[:]))
    '[' => TomlArray(parse_array_value(s[:]))
    _ => TomlInt(parse_int_value(s[:]))
  }
}

///|
/// Split a dotted key into its segments. Handles bare keys only.
fn split_dotted_key(key_str : StringView) -> Array[String] {
  let owned = key_str.trim().to_owned()
  let parts : Array[String> = []
  let mut current = StringBuilder()
  for c in owned.iter() {
    if c == '.' {
      let seg = current.to_string().trim()
      if !seg.is_empty() {
        parts.push(seg)
      }
      current = StringBuilder()
    } else {
      current.write_char(c)
    }
  }
  let seg = current.to_string().trim()
  if !seg.is_empty() {
    parts.push(seg)
  }
  parts
}

///|
/// Set a value at a dotted key path in a map, creating intermediate maps as needed.
fn set_at_path(
  map : Map[String, Json],
  path : Array[String],
  value : TomlValue,
) -> Unit raise TomlError {
  if path.length() == 1 {
    let key = path[0]
    if map.has_key(key) {
      raise TomlDuplicateKey("duplicate key: " + key)
    }
    map[key] = value.to_json()
    return
  }
  // Navigate/create intermediate path
  let mut current = map
  for i in 0..<(path.length() - 1) {
    let key = path[i]
    if current.has_key(key) {
      match current[key] {
        Json::Object(inner) => current = inner
        _ => raise TomlDuplicateKey(
          "key '{}' is already defined as a non-table value".format_with([key]),
        )
      }
    } else {
      let new_map : Map[String, Json] = {}
      current[key] = Json::object(new_map)
      current = new_map
    }
  }
  let last_key = path[path.length() - 1]
  if current.has_key(last_key) {
    raise TomlDuplicateKey("duplicate key: " + last_key)
  }
  current[last_key] = value.to_json()
}

///|
/// Parse a TOML document into a Json object that preserves document order.
pub fn parse(toml_text : String) -> Map[String, Json] raise TomlError {
  let raw_lines : Array[String> = []
  for line in toml_text.split("\n") {
    raw_lines.push(line)
  }

  // Filter: strip comments, trim, skip blank
  let lines : Array[String> = []
  for line in raw_lines {
    let comment_stripped = strip_comment(line)
    let trimmed = comment_stripped.trim()
    let clean = trimmed.to_owned()
    if !clean.trim().is_empty() {
      lines.push(clean.trim())
    }
  }

  let root : Map[String, Json] = {}
  let mut current_table_path : Array[String> = []
  let mut current_map : Map[String, Json] = root

  for i in 0..<lines.length() {
    let line = lines[i]
    let chars = line.to_array()
    if chars[0] == '[' {
      // Table header
      if chars[chars.length() - 1] != ']' {
        raise TomlSyntaxError("malformed table header: " + line)
      }
      let header_view = line[1:chars.length() - 1]
      let path = split_dotted_key(header_view[:])
      if path.length() == 0 {
        raise TomlSyntaxError("empty table name")
      }
      current_table_path = path
      // Navigate to the right table
