    } else {
      // Key = value
      let eq_pos = find_first_unquoted_eq(line[:])
      if eq_pos < 0 {
        raise TomlSyntaxError("invalid line (no '=' found): " + line)
      }
      let key_sv = line[0:eq_pos].trim()
      let val_sv = line[eq_pos + 1:]
      if val_sv.trim().is_empty() {
        raise TomlSyntaxError("missing value for key: " + key_sv.to_owned())
      }
      let value = parse_value(val_sv[:])
      let key_path = split_dotted_key(key_sv[:])
      if key_path.length() == 0 {
        raise TomlSyntaxError("empty key")
      }
      set_at_path(current_map, key_path, value)
    }
  }
  root
}

///|
/// Parse TOML into a JSON string.
pub fn to_json_string(toml_text : String) -> String raise TomlError {
  let map = parse(toml_text)
  Json::object(map).stringify()
}
