{"path": "/private/tmp/prompt_matrix/runs_flash-x-baseprompt/workspaces/03/toml_parser.mbt", "content": "///|
/// Internal TOML value type.
enum TomlValue {
  TomlStr(String)
  TomlInt(Int)
  TomlBool(Bool)
  TomlArray(Array[TomlValue])
} derive(Debug)

///|
fn TomlValue::to_json(self : TomlValue) -> Json {
  match self {
    TomlStr(s) => Json::string(s)
    TomlInt(n) => Json::number(n.to_double())
    TomlBool(b) => Json::boolean(b)
    TomlArray(a) => Json::array(a.map(fn(v) { v.to_json() }))
  }
}

///|
/// Strip inline comment (#) from a line, respecting quoted strings.
fn strip_comment(line : String) -> String {
  let mut in_string = false
  let mut escape = false
  let chars : Array[Char] = []
  for c in line.iter() {
    if escape {
      chars.push(c)
      escape = false
    } else if c == '\\' {
      chars.push(c)
      escape = true
    } else if c == '"' {
      chars.push(c)
      in_string = !in_string
    } else if c == '#' && !in_string {
      break
    } else {
      chars.push(c)
    }
  }
  String::from_iter(chars.iter())
}

///|
/// Find the position of the first unquoted '=' character in a StringView.
fn find_first_unquoted_eq(s : StringView) -> Int {
  let mut in_string = false
  let mut escape = false
  let chars = s.to_array()
  for i in 0..<chars.length() {
    let c = chars[i]
    if escape {
      escape = false
    } else if c == '\\' {
      escape = true
    } else if in_string {
      if c == '"' {
        in_string = false
      }
    } else if c == '"' {
      in_string = true
    } else if c == '=' {
      return i
    }
  }
  -1
}

///|
/// Parse a basic string content (quotes already stripped), handling escapes.
fn parse_string_content(content : String) -> String raise TomlError {
  let result : Array[Char] = []
  let chars : Array[Char] = Array::from_iter(content.iter())
  let mut i = 0
  while i < chars.length() {
    let c = chars[i]
    if c == '\\' {
      if i + 1 >= chars.length() {
        raise TomlSyntaxError("truncated escape sequence")
      }
      let next = chars[i + 1]
      result.push(
        match next {
          '"' => '"'
          '\\' => '\\'
          'n' => '\n'
          't' => '\t'
          _ => raise TomlSyntaxError("invalid escape sequence: \{next}")
        },
      )
      i += 2
    } else {
      result.push(c)
      i += 1
    }
  }
  String::from_iter(result.iter())
}

///|
/// Parse a quoted string value (including surrounding quotes).
fn parse_string_value(raw : StringView) -> String raise TomlError {
  let trimmed = raw.trim()
  let chars = trimmed.to_array()
  if chars.length() < 2 || chars[0] != '"' {
    raise TomlSyntaxError("expected a quoted string, got: " + trimmed.to_owned())
  }
  // Find the closing quote (respecting escapes)
  let mut end = -1
  let mut escape = false
  for i in 1..<chars.length() {
    if escape {
      escape = false
    } else if chars[i] == '\\' {
      escape = true
    } else if chars[i] == '"' {
      end = i
      break
    }
  }
  if end < 0 {
    raise TomlSyntaxError("unclosed string")
  }
  let inner = String::from_iter(chars[1:end].iter())
  parse_string_content(inner)
}

///|
/// Parse an integer from a string view.
fn parse_int_value(s : StringView) -> Int raise TomlError {
  let t = s.trim()
  try @string.parse_int64(t) catch {
    _ => raise TomlSyntaxError("cannot parse integer: " + t.to_owned())
  } noraise {
    v => v.to_int()
  }
}

///|
/// Parse a boolean from a string view.
fn parse_bool_value(s : StringView) -> Bool raise TomlError {
  let t = s.trim().to_owned()
  match t {
    "true" => true
    "false" => false
    _ => raise TomlSyntaxError("cannot parse boolean: " + t)
  }
}

///|
/// Parse an array of values from a string view.
fn parse_array_value(s : StringView) -> Array[TomlValue] raise TomlError {
  let t = s.trim()
  let chars = t.to_array()
  if chars.length() < 2 || chars[0] != '[' {
    raise TomlSyntaxError("expected array, got: " + t.to_owned())
  }
  // Find matching closing bracket
  let mut depth = 0
  let mut in_str = false
  let mut escape = false
  let mut bracket_end = -1
  for i in 0..<chars.length() {
    let c = chars[i]
    if escape {
      escape = false
    } else if c == '\\' {
      escape = true
    } else if in_str {
      if c == '"' {
        in_str = false
      }
    } else if c == '"' {
      in_str = true
    } else if c == '[' {
      depth += 1
    } else if c == ']' {
      depth -= 1
      if depth == 0 {
        bracket_end = i
        break
      }
    }
  }
  if bracket_end < 0 {
    raise TomlSyntaxError("unclosed array")
  }
  // Extract content between brackets
  let inner_sv = chars[1:bracket_end]
  let inner_str = String::from_iter(inner_sv.iter())
  let inner = inner_str.trim()
  if inner.is_empty() {
    return []
  }
  // Split by comma respecting nesting and strings
  let inner_chars = inner.to_array()
  let items : Array[TomlValue] = []
  let mut seg_start = 0
  let mut string_depth = 0
  let mut array_depth = 0
  let mut esc = false
  for i in 0..<inner_chars.length() {
    let c = inner_chars[i]
    if esc {
      esc = false
    } else if c == '\\' {
      esc = true
    } else if string_depth > 0 {
      if c == '"' {
        string_depth = 0
      }
    } else if c == '"' {
      string_depth = 1
    } else if c == '[' {
      array_depth += 1
    } else if c == ']' {
      array_depth -= 1
    } else if c == ',' && array_depth == 0 {
      let item_sv = inner_chars[seg_start:i]
      let item_str = String::from_iter(item_sv.iter())
      items.push(parse_value(item_str[:]))
      seg_start = i + 1
    }
  }
  if seg_start < inner_chars.length() {
    let last_sv = inner_chars[seg_start:]
    let last_str = String::from_iter(last_sv.iter())
    items.push(parse_value(last_str[:]))
  }
  items
}

///|
/// Parse a single TOML value from its string representation.
fn parse_value(s : StringView) -> TomlValue raise TomlError {
  let t = s.trim()
  if t.is_empty() {
    raise TomlSyntaxError("empty value")
  }
  let chars = t.to_array()
  let first = chars[0]
  match first {
    '"' => TomlStr(parse_string_value(s))
    't' | 'f' => TomlBool(parse_bool_value(s))
    '[' => TomlArray(parse_array_value(s))
    _ => TomlInt(parse_int_value(s))
  }
}

///|
/// Split a dotted key into its segments (bare keys only).
fn split_dotted_key(key_str : StringView) -> Array[String] {
  let owned = key_str.trim().to_owned()
  let parts : Array[String] = []
  let mut current = StringBuilder()
  for c in owned.iter() {
    if c == '.' {
      let seg = current.to_string().trim()
      if !seg.is_empty() {
        parts.push(seg.to_owned())
      }
      current = StringBuilder()
    } else {
      current.write_char(c)
    }
  }
  let seg = current.to_string().trim()
  if !seg.is_empty() {
    parts.push(seg.to_owned())
  }
  parts
}

///|
/// Set a value at a dotted key path in a map, creating intermediate maps.
fn set_at_path(
  map : Map[String, Json],
  path : Array[String],
  value : TomlValue,
) -> Unit raise TomlError {
  if path.length() == 1 {
    let key = path[0]
    if map.contains(key) {
      raise TomlDuplicateKey("duplicate key: " + key)
    }
    map[key] = value.to_json()
    return
  }
  let mut current = map
  for i in 0..<(path.length() - 1) {
    let key = path[i]
    if current.contains(key) {
      match current[key] {
        Json::Object(inner) => current = inner
        _ => raise TomlDuplicateKey(
          "key '\{key}' is already defined as a non-table value",
        )
      }
    } else {
      let new_map : Map[String, Json] = {}
      current[key] = Json::object(new_map)
      current = new_map
    }
  }
  let last_key = path[path.length() - 1]
  if current.contains(last_key) {
    raise TomlDuplicateKey("duplicate key: " + last_key)
  }
  current[last_key] = value.to_json()
}

///|
/// Parse a TOML document into an ordered Map[String, Json].
pub fn parse(toml_text : String) -> Map[String, Json] raise TomlError {
  // Collect non-blank, comment-stripped, trimmed lines
  let lines : Array[String] = []
  for sv in toml_text.split("\n") {
    let raw_line = sv.to_owned()
    let stripped = strip_comment(raw_line)
    let trimmed = stripped.trim()
    if !trimmed.is_empty() {
      lines.push(trimmed.to_owned())
    }
  }

  let root : Map[String, Json] = {}
  let mut current_map : Map[String, Json] = root

  for i in 0..<lines.length() {
    let line = lines[i]
    let chars = line.to_array()
    if chars[0] == '[' {
      // Table header
      let last_idx = chars.length() - 1
      if chars[last_idx] != ']' {
        raise TomlSyntaxError("malformed table header: " + line)
      }
      let header_sv = chars[1:last_idx]
      let header_str = String::from_iter(header_sv.iter())
      let path = split_dotted_key(header_str[:])
      if path.length() == 0 {
        raise TomlSyntaxError("empty table name")
      }
      // Navigate to the right sub-map
      current_map = root
      for key in path {
        if current_map.contains(key) {
          match current_map[key] {
            Json::Object(inner) => current_map = inner
            _ => raise TomlDuplicateKey(
              "key '\{key}' is already defined as a non-table value",
            )
          }
        } else {
          let new_map : Map[String, Json] = {}
          current_map[key] = Json::object(new_map)
          current_map = new_map
        }
      }
    } else {
      // Key = value
      let eq_pos = find_first_unquoted_eq(line[:])
      if eq_pos < 0 {
        raise TomlSyntaxError("invalid line (no '=' found): " + line)
      }
      let key_sv = line[0:eq_pos].trim()
      let val_sv = line[eq_pos + 1:]
      if val_sv.trim().is_empty() {
        raise TomlSyntaxError("missing value for key: " + key_sv.to_owned())
      }
      let value = parse_value(val_sv[:])
      let key_path = split_dotted_key(key_sv[:])
      if key_path.length() == 0 {
        raise TomlSyntaxError("empty key")
      }
      set_at_path(current_map, key_path, value)
    }
  }
  root
}

///|
/// Parse TOML into a JSON string.
pub fn to_json_string(toml_text : String) -> String raise TomlError {
  let map = parse(toml_text)
  Json::object(map).stringify()
}
"}

