fn main {
  let args = @argparse.parse(
    @argparse.Command::new(
      "tomljson",
      "Convert TOML to JSON",
      ~options=[
        @argparse.FlagArg(long="stdin", help="Read TOML from stdin"),
        @argparse.ArgArg(long="file", short='f', help="Path to TOML file"),
      ],
      ~rest=[@argparse.ArgArg(long="FILE", help="Path to TOML file")],
    ),
  )

  // Determine input source
  // Priority: positional FILE arg > --file arg > --stdin
  let stdin_mode = args.contains_key("stdin")
  let file_opt = args.opt("file")
  let pos_files = args.rest()

  let content : String =
    if pos_files.length() > 0 {
      let path = pos_files[0]
      read_file(path)
    } else if file_opt is Some(path) {
      read_file(path)
    } else if stdin_mode {
      read_stdin()
    } else {
      print_usage_and_exit()
    }

  try parse_and_print(content) catch {
    TomlSyntaxError(msg) | TomlDuplicateKey(msg) => {
      @stdio.stderr.write_string("Error: " + msg + "\n")
    }
  } noraise {
    _ => ()
  }
}

///|
fn parse_and_print(content : String) -> Unit raise TomlError {
  let json_str = @tomlkit.to_json_string(content)
  println(json_str)
}

///|
fn read_file(path : String) -> String {
  // Use a simple approach with fopen/read
  let file = try @file.open(path, "r") catch {
    _ => {
      @stdio.stderr.write_string("Error: cannot open file: " + path + "\n")
      exit(1)
    }
  } noraise {
    f => f
  }
  let sb = StringBuilder()
  loop {
    match file.read_line() {
      Some(line) => sb.write_string(line)
      None => break
    }
  } nobreak {
    file.close()
  }
  sb.to_string()
}

///|
fn read_stdin() -> String {
  let sb = StringBuilder()
  loop {
    match @stdio.stdin.read_line() {
      Some(line) => sb.write_string(line)
      None => break
    }
  } nobreak {
    ()
  }
  sb.to_string()
}

///|
fn print_usage_and_exit() -> String {
  @stdio.stderr.write_string(
    "Usage: tomljson [--stdin | --file PATH | PATH]\n",
  )
  exit(1)
}
"}

